# 状态化 mock:create 后 get 能读到(FSM)
class MockOrderFSM:
    def __init__(self): self.orders = {}
    async def create(self, args):
        self.orders[args["order_id"]] = {"status": "created"}
        return {"ok": True, "data": {"id": args["order_id"]}}
    async def get(self, args):
        o = self.orders.get(args["order_id"])
        return o if o else {"ok": False,
            "error": {"code": "NOT_FOUND", "message": f"订单 {args['order_id']} 不存在"}}
```

